import { CommonModule } from '@angular/common';
import { Component, inject } from '@angular/core';
import { Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { ApiService } from '../../../core/services/api.service';
import { AuthService } from '../../../core/services/auth.service';

@Component({
  selector: 'app-master-template',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './master-template.component.html',
  styleUrl: './master-template.component.css',
})
export class MasterTemplateComponent {
  private readonly apiService = inject(ApiService);
  private readonly router = inject(Router);
  private readonly authService = inject(AuthService);

  readonly moduleId = 1010;

  get canAccessPage(): boolean {
    return this.authService.hasPermission(this.moduleId, 'r');
  }

  get canDelete(): boolean {
    return this.authService.hasPermission(this.moduleId, 'd');
  }

  get canUse(): boolean {
    return this.authService.hasPermission(2001, 'c');
  }

  rows: any[] = [];
  loading = false;
  errorMessage = '';
  deleting = false;
  usingId: number | null = null;

  constructor() {
    if (!this.canAccessPage) {
      return;
    }

    this.loadRows();
  }

  loadRows(): void {
    this.loading = true;
    this.errorMessage = '';

    this.apiService.get('/project/templates').subscribe({
      next: (response) => {
        this.loading = false;
        this.rows = (Array.isArray(response?.data) ? response.data : []).map(
          (row: any) => ({ ...row, checked: false }),
        );
        this.updateDeleteState();
      },
      error: (error) => {
        this.loading = false;
        this.rows = [];
        this.updateDeleteState();
        this.errorMessage =
          error?.error?.message || 'Failed to load template data.';
      },
    });
  }

  trackById(_: number, row: any): any {
    return row?.id;
  }

  disabledDelete = true;

  toggleRowChecked(row: any): void {
    row.checked = !row.checked;
    this.updateDeleteState();
  }

  async useTemplate(row: any): Promise<void> {
    if (this.usingId !== null || !this.canUse) {
      return;
    }

    const id = String(row?.id ?? '').trim();

    if (!id) {
      return;
    }

    const confirmed = confirm(`Create a new draft from template "${row?.name || id}"?`);

    if (!confirmed) {
      return;
    }

    this.usingId = Number(row?.id) || null;
    this.errorMessage = '';

    try {
      const response = await firstValueFrom(
        this.apiService.post(`/project/template/${id}/instantiate`, {}),
      );

      const draftId = String(response?.data?.id ?? '').trim();

      if (!draftId) {
        this.errorMessage = 'Failed to create draft from template.';
        return;
      }

      await this.router.navigate(['/project/create', draftId]);
    } catch (error: any) {
      this.errorMessage = error?.error?.message || 'Failed to create draft from template.';
    } finally {
      this.usingId = null;
    }
  }

  async deleteSelected(): Promise<void> {
    if (this.deleting || !this.canDelete) {
      return;
    }

    const selectedRows = this.rows.filter((row) => Boolean(row?.checked));

    if (!selectedRows.length) {
      this.updateDeleteState();
      return;
    }

    const ids = selectedRows
      .map((row) => String(row?.id || '').trim())
      .filter((id) => id.length > 0);

    if (!ids.length) {
      this.errorMessage = 'Selected rows contain invalid template id.';
      this.updateDeleteState();
      return;
    }

    const confirmed = confirm(`Delete ${ids.length} selected template(s)?`);

    if (!confirmed) {
      return;
    }

    this.deleting = true;
    this.errorMessage = '';

    try {
      const results = await Promise.allSettled(
        ids.map((id) => firstValueFrom(this.apiService.delete(`/project/template/${id}`))),
      );

      const failedCount = results.filter(
        (result) => result.status === 'rejected',
      ).length;

      if (failedCount > 0) {
        this.errorMessage = `${failedCount} template(s) failed to delete.`;
      }

      this.loadRows();
    } catch {
      this.errorMessage = 'Failed to delete selected template(s).';
    } finally {
      this.deleting = false;
    }
  }

  private updateDeleteState(): void {
    this.disabledDelete =
      this.deleting || !this.canDelete || !this.rows.some((row) => Boolean(row?.checked));
  }
}
