import { Routes } from '@angular/router';
import { authGuard } from './core/guards/auth.guard';
import { LoginComponent } from './features/auth/login/login.component';
import { MasterHomeComponent } from './features/master/master-home/master-home.component';
import { MasterManageComponent } from './features/master/master-manage/master-manage.component';
import { MasterTicketCategoriesComponent } from './features/master/master-ticket-categories/master-ticket-categories.component';
import { MasterTicketCategoryDetailComponent } from './features/master/master-ticket-categories/master-ticket-category-detail/master-ticket-category-detail.component';
import { MasterProductComponent } from './features/master/master-product/master-product.component';
import { MasterProductDetailComponent } from './features/master/master-product/master-product-detail/master-product-detail.component';
import { HomeComponent } from './features/home/home.component';
import { ClientListComponent } from './features/client/client-list/client-list.component';
import { ClientDetailComponent } from './features/client/client-detail/client-detail.component';
import { UserListComponent } from './features/user/user-list/user-list.component';
import { UserDetailComponent } from './features/user/user-detail/user-detail.component';
import { UserLoginHistoryListComponent } from './features/user-login-history/user-login-history-list/user-login-history-list.component';
import { TicketBalanceHistoryListComponent } from './features/ticket-balance-history/ticket-balance-history-list/ticket-balance-history-list.component';
import { TicketHistoryListComponent } from './features/ticket-history/ticket-history-list/ticket-history-list.component';
import { ProjectListComponent } from './features/project/project-list/project-list.component';
import { ProjectCreateComponent } from './features/project/project-create/project-create.component';
import { ProjectDetailComponent } from './features/project/project-detail/project-detail.component';
import { MasterTemplateComponent } from './features/master/master-template/master-template.component';
import { MasterTemplateDetailComponent } from './features/master/master-template/master-template-detail/master-template-detail.component';
import { TaskListComponent } from './features/task/task-list/task-list.component';
import { TaskDetailComponent } from './features/task/task-detail/task-detail.component';
import { CaseListComponent } from './features/cases/case-list/case-list.component';
import { CaseDetailComponent } from './features/cases/case-detail/case-detail.component';
import { ChangeRequestListComponent } from './features/change-requests/change-request-list/change-request-list.component';
import { ChangeRequestDetailComponent } from './features/change-requests/change-request-detail/change-request-detail.component';
import { RatingListComponent } from './features/rating/rating-list/rating-list.component';
import { TaskReportComponent } from './features/reports/task-report/task-report.component';
import { CaseReportComponent } from './features/reports/case-report/case-report.component';
import { AdminLayoutComponent } from './layout/admin-layout/admin-layout.component';
import { NotFoundComponent } from './layout/not-found/not-found.component';
import { ReloginComponent } from './features/auth/relogin/relogin.component';
import { CrReportComponent } from './features/reports/cr-report/cr-report.component';
import { VerificationListComponent } from './features/verification/verification-list/verification-list.component';
import { UsersReportComponent } from './features/reports/users-report/users-report.component';
import { UserDetailReportComponent } from './features/reports/users-report/user-detail-report/user-detail-report.component';
 
export const routes: Routes = [
	{
		path: 'login',
		component: LoginComponent,
	},
	{
		path: 'relogin',
		component: ReloginComponent,
	},
	{
		path: '',
		component: AdminLayoutComponent,
		canActivate: [authGuard],
		children: [
			{
				path: '',
				pathMatch: 'full',
				redirectTo: 'home',
			},
			{
				path: 'home',
				component: HomeComponent,
			},
			{
				path: 'clients',
				component: ClientListComponent,
			},
			{
				path: 'clients/:id',
				component: ClientDetailComponent,
			},
			{
				path: 'users',
				component: UserListComponent,
			},
			{
				path: 'user-login-history',
				component: UserLoginHistoryListComponent,
			},
			{
				path: 'ticket-balance-history',
				component: TicketBalanceHistoryListComponent,
			},
			{
				path: 'ticket',
				component: TicketHistoryListComponent,
			},
			{
				path: 'users/:id',
				component: UserDetailComponent,
			},
			{
				path: 'projects',
				component: ProjectListComponent,
			},
			{
				path: 'project/create/:id',
				component: ProjectCreateComponent,
			},
			{
				path: 'project/:id',
				component: ProjectDetailComponent,
			},
			{
				path: 'tasks',
				component: TaskListComponent,
			},
			{
				path: 'tasks/:id',
				component: TaskDetailComponent,
			},
			{
				path: 'cases',
				component: CaseListComponent,
			},
			{
				path: 'cases/:id',
				component: CaseDetailComponent,
			},
			{
				path: 'change-requests',
				component: ChangeRequestListComponent,
			},
			{
				path: 'change-requests/:id',
				component: ChangeRequestDetailComponent,
			},
			{
				path: 'rating',
				component: RatingListComponent,
			},
			{
				path: 'report/task',
				component: TaskReportComponent,
			},
			{
				path: 'report/cases',
				component: CaseReportComponent,
		 
			},
			{
				path: 'report/change-requests',
				component: CrReportComponent,
			},


			{
				path: 'report/users',
				component: UsersReportComponent,
			},
			{
				path: 'report/users/:id',
				component: UserDetailReportComponent,
			},


			{
				path: 'verification',
				component: VerificationListComponent,
			},

			{
				path: 'master',
				component: MasterHomeComponent,
			},
			{
				path: 'master-ticket-categories',
				component: MasterTicketCategoriesComponent,
			},
			{
				path: 'master-ticket-categories/:id',
				component: MasterTicketCategoryDetailComponent,
			},
			{
				path: 'master-product',
				component: MasterProductComponent,
			},
			{
				path: 'master-product/:id',
				component: MasterProductDetailComponent,
			},
			{
				path: 'master-template',
				component: MasterTemplateComponent,
			},
			{
				path: 'master-template/:id',
				component: MasterTemplateDetailComponent,
			},
			 
			{
				path: 'master/:masterKey',
				component: MasterManageComponent,
			},
			
		],
	},
	{
		path: '**',
		component: NotFoundComponent,
	},

];
