import { CommonModule } from '@angular/common';
import { Component, OnInit, inject } from '@angular/core';
import { FormsModule, NgForm } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../../core/services/auth.service';
import { environment } from '../../../../environments/environment';
import { buildInfo } from './../../../../environments/build-info';
interface LoginForm {
  email: string;
  password: string;
  remember: boolean;
}

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './login.component.html',
  styleUrl: './login.component.css',
})
export class LoginComponent implements OnInit {
  private readonly authService = inject(AuthService);
  private readonly router = inject(Router);
  env: any = environment;
  formModel: LoginForm = {
    email: '',
    password: '',
    remember: true,
  };
  ngBuildCode: string = buildInfo.buildCode; // auto-generated on each build
  loading = false;
  errorMessage = '';
  showPassword = false;

  ngOnInit(): void {
    if (this.env.production !== true) {
      this.formModel.email = 'admin@thinktank.local';
      this.formModel.password = 'Admin123!';
    }
    if (this.authService.isAuthenticated) {
      void this.router.navigateByUrl('/master');
    }
  }

  onSubmit(form: NgForm): void {
    if (form.invalid || this.loading) {
      return;
    }

    this.loading = true;
    this.errorMessage = '';

    this.authService
      .login({
        email: this.formModel.email,
        password: this.formModel.password,
      })
      .subscribe({
        next: () => {
          this.loading = false;
          void this.router.navigateByUrl('/home');
        },
        error: (error) => {
          this.loading = false;
          this.errorMessage =
            error?.error?.message || 'Login failed. Please try again.';
        },
      });
  }

  togglePassword(): void {
    this.showPassword = !this.showPassword;
  }
}
