import { CommonModule } from '@angular/common';
import { Component, OnInit, inject } from '@angular/core';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { FormsModule, NgForm } from '@angular/forms';
import { NgbNavModule } from '@ng-bootstrap/ng-bootstrap';
import { ApiService } from '../../../core/services/api.service';
import { AuthService } from '../../../core/services/auth.service';

interface UserFormModel {
  email: string;
  userAuthLevelId: number;
  firstName: string;
  lastName: string;
  phone: string;
  mobile: string;
  division: string;
  position: string;
  userTypeId: number;
  clientId: number;
  status: number;
}

@Component({
  selector: 'app-user-detail',
  standalone: true,
  imports: [CommonModule, FormsModule, RouterLink, NgbNavModule],
  templateUrl: './user-detail.component.html',
  styleUrl: './user-detail.component.css',
})
export class UserDetailComponent implements OnInit {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly apiService = inject(ApiService);
  private readonly authService = inject(AuthService);

  readonly moduleId = 2004;

  get canAccessPage(): boolean {
    return this.authService.hasPermission(this.moduleId, 'r');
  }

  get canUpdate(): boolean {
    return this.authService.hasPermission(this.moduleId, 'u');
  }

  get canDelete(): boolean {
    return this.authService.hasPermission(this.moduleId, 'd');
  }

  userId: string | null = null;
  user: any = null;
  loading = false;
  saving = false;
  changingPassword = false;
  newPassword = '';
  confirmPassword = '';
  showPassword = false;
  message = '';
  errorMessage = '';

  userForm: UserFormModel = this.defaultForm();
  formMode: 'view' | 'edit' = 'view';
  active = 1;
  accessRightOptions: any[] = [];
  products: any[] = [];
  loadingProducts = false;
  projects: any[] = [];
  clients: any[] = [];
  loadingProjects = false;
  loadingClients = false;
  clientKeyword = '';
  projectKeyword = '';

  ngOnInit(): void {
    if (!this.canAccessPage) {
      return;
    }

    this.loadAccessRightOptions();
    this.userId = this.route.snapshot.paramMap.get('id');
    if (this.userId) {
      this.loadUserDetail();
      this.loadProducts();
      this.loadProjects();
      this.loadClients();
    }
  }

  loadAccessRightOptions(): void {
    this.apiService.get('/master/user-auth-level').subscribe({
      next: (response) => {
        this.accessRightOptions = Array.isArray(response?.data) ? response.data : [];
      },
      error: () => {
        this.accessRightOptions = [];
      },
    });
  }

  loadUserDetail(): void {
    if (!this.userId) {
      return;
    }

    this.loading = true;
    this.errorMessage = '';

    this.apiService.get(`/user/${this.userId}`).subscribe({
      next: (response) => {
        this.loading = false;
        this.user = response?.data;
        this.populateFormFromUser();
      },
      error: (error) => {
        this.loading = false;
        this.errorMessage = error?.error?.message || 'Failed to load user.';
      },
    });
  }

  loadProducts(): void {
    if (!this.userId) {
      return;
    }

    this.loadingProducts = true;
    this.apiService.get(`/user/${this.userId}/products`).subscribe({
      next: (response) => {
        this.loadingProducts = false;
        this.products = Array.isArray(response?.data) ? response.data : [];
      },
      error: () => {
        this.loadingProducts = false;
        this.products = [];
      },
    });
  }

  loadProjects(): void {
    if (!this.userId) {
      return;
    }

    this.loadingProjects = true;
    this.apiService.get(`/user/${this.userId}/projects`).subscribe({
      next: (response) => {
        this.loadingProjects = false;
        this.projects = Array.isArray(response?.data) ? response.data : [];
      },
      error: () => {
        this.loadingProjects = false;
        this.projects = [];
      },
    });
  }

  loadClients(): void {
    if (!this.userId) {
      return;
    }

    this.loadingClients = true;
    this.apiService.get(`/user/${this.userId}/clients`).subscribe({
      next: (response) => {
        this.loadingClients = false;
        this.clients = Array.isArray(response?.data) ? response.data : [];
      },
      error: () => {
        this.loadingClients = false;
        this.clients = [];
      },
    });
  }

  get filteredClients(): any[] {
    const keyword = this.clientKeyword.trim().toLowerCase();
    if (!keyword) {
      return this.clients;
    }

    return this.clients.filter((client) =>
      [client.code, client.name, client.industryName, client.relation]
        .filter((value) => value !== null && value !== undefined && value !== '')
        .some((value) => String(value).toLowerCase().includes(keyword))
    );
  }

  get filteredProjects(): any[] {
    const keyword = this.projectKeyword.trim().toLowerCase();
    if (!keyword) {
      return this.projects;
    }

    return this.projects.filter((project) =>
      [
        project.id,
        project.name,
        project.clientName,
        project.projectTypeName,
        project.productName,
        project.roleName,
        project.projectBilleableName,
      ]
        .filter((value) => value !== null && value !== undefined && value !== '')
        .some((value) => String(value).toLowerCase().includes(keyword))
    );
  }

  onProductToggle(product: any, event: Event): void {
    const input = event.target as HTMLInputElement;
    product.checked = input.checked ? 1 : 0;
  }

  startEdit(): void {
    if (!this.user || !this.canUpdate) {
      return;
    }

    this.formMode = 'edit';
    this.populateFormFromUser();
    this.message = '';
    this.errorMessage = '';
  }

  cancelEdit(): void {
    this.formMode = 'view';
    this.populateFormFromUser();
    this.loadProducts();
    this.errorMessage = '';
  }

  saveUser(form: NgForm): void {
    if (form.invalid || this.saving || !this.userId || !this.canUpdate) {
      return;
    }

    const payload: Record<string, any> = {
      email: this.userForm.email.trim(),
      userAuthLevelId: Number(this.userForm.userAuthLevelId),
      firstName: this.userForm.firstName.trim(),
      lastName: this.userForm.lastName.trim(),
      phone: this.userForm.phone.trim(),
      mobile: this.userForm.mobile.trim(),
      division: this.userForm.division.trim(),
      position: this.userForm.position.trim(),
      userTypeId: Number(this.userForm.userTypeId),
      clientId: Number(this.userForm.clientId),
      status: Number(this.userForm.status),
    };

    this.saving = true;
    this.message = '';
    this.errorMessage = '';

    this.apiService.put(`/user/${this.userId}`, payload).subscribe({
      next: () => {
        this.saveUserProducts();
      },
      error: (error) => {
        this.saving = false;
        this.errorMessage = error?.error?.message || 'Failed to update user.';
      },
    });
  }

  private saveUserProducts(): void {
    if (!this.userId) {
      this.saving = false;
      this.goBack();
      return;
    }

    const productIds = this.products
      .filter((product) => Number(product?.checked) === 1)
      .map((product) => Number(product.id));

    this.apiService.put(`/user/${this.userId}/products`, { productIds }).subscribe({
      next: (response) => {
        this.saving = false;
        this.message = response?.message || 'User updated.';
        this.formMode = 'view';
        this.goBack();
      },
      error: (error) => {
        this.saving = false;
        this.errorMessage = error?.error?.message || 'Failed to update user products.';
      },
    });
  }

  changePassword(): void {
    if (!this.userId || this.changingPassword || !this.canUpdate) {
      return;
    }

    if (!this.newPassword) {
      this.errorMessage = 'New password is required.';
      return;
    }

    if (this.newPassword !== this.confirmPassword) {
      this.errorMessage = 'Password confirmation does not match.';
      return;
    }

    this.changingPassword = true;
    this.message = '';
    this.errorMessage = '';

    this.apiService
      .put(`/user/${this.userId}/password`, {
        password: this.newPassword,
        confirmPassword: this.confirmPassword,
      })
      .subscribe({
        next: (response) => {
          this.changingPassword = false;
          this.newPassword = '';
          this.confirmPassword = '';
          this.showPassword = false;
          this.message = response?.message || 'Password updated.';
          history.back();
        },
        error: (error) => {
          this.changingPassword = false;
          this.errorMessage = error?.error?.message || 'Failed to update password.';
        },
      });
  }

  onUserTypeChange(): void {
    if (Number(this.userForm.userTypeId) === 1) {
      this.userForm.clientId = 0;
    }
  }

  deleteUser(): void {
    if (!this.userId || !this.canDelete) {
      return;
    }

    const confirmed = confirm(`Delete user ${this.user?.email || this.userId}?`);
    if (!confirmed) {
      return;
    }

    this.apiService.delete(`/user/${this.userId}`).subscribe({
      next: (response) => {
        alert(response?.message || 'User deleted.');
        this.router.navigate(['/users']);
      },
      error: (error) => {
        this.errorMessage = error?.error?.message || 'Failed to delete user.';
      },
    });
  }

  goBack(): void {
    history.back();
  }

  private defaultForm(): UserFormModel {
    return {
      email: '',
      userAuthLevelId: 1,
      firstName: '',
      lastName: '',
      phone: '',
      mobile: '',
      division: '',
      position: '',
      userTypeId: 1,
      clientId: 0,
      status: 1,
    };
  }

  private populateFormFromUser(): void {
    this.userForm = {
      email: String(this.user?.email || ''),
      userAuthLevelId: Number(this.user?.userAuthLevelId ?? 1),
      firstName: String(this.user?.firstName || ''),
      lastName: String(this.user?.lastName || ''),
      phone: String(this.user?.phone || ''),
      mobile: String(this.user?.mobile || ''),
      division: String(this.user?.division || ''),
      position: String(this.user?.position || ''),
      userTypeId: Number(this.user?.userTypeId ?? 1),
      clientId: Number(this.user?.clientId ?? 0),
      status: Number(this.user?.status ?? 1),
    };
  }

  private buildAccessRightLabel(row: any): string {
    const id = Number(row?.id);
    const authLevelId = Number(row?.authLevelId ?? 0);
    const name = String(row?.name ?? '');
    const status = Number(row?.status ?? 0) === 1 ? 'Active' : 'Inactive';

    return `#${id} - Auth ${authLevelId} / Module ${name} (${status})`;
  }
}
